/**
 * P2P Asset Pack Sharing Protocol
 *
 * Manages the consent-based exchange of asset pack data between peers
 * during lobby/matchmaking. Supports card-only (default) and full-pack
 * transfer modes with per-player blocking and rate limiting.
 *
 * Protocol flow:
 * 1. Both players share deck lists after P2P connection
 * 2. Receiver checks for missing card IDs
 * 3. Receiver sends asset-pack-request
 * 4. Sender sees consent prompt → allow/deny/block
 * 5. If allowed, sender sends asset-pack-offer with size info
 * 6. Receiver sees accept prompt → accept/decline/block
 * 7. If accepted, sender streams chunks
 * 8. Receiver reassembles and caches in IndexedDB
 */

import type { Chunk } from './chunking';

// ---------------------------------------------------------------------------
// P2P Message Types for Asset Sharing
// ---------------------------------------------------------------------------

export type AssetSharingMessageType =
  | 'deck-list-share'
  | 'deck-list-ack'
  | 'asset-pack-request'
  | 'asset-pack-offer'
  | 'asset-pack-chunk'
  | 'asset-pack-complete'
  | 'asset-pack-denied'
  | 'asset-pack-cancel';

/** Deck list shared during lobby. */
export interface DeckListShareMessage {
  type: 'deck-list-share';
  deckList: {
    name: string;
    game: string;
    pack: string;
    leader: string;
    cards: Record<string, number>;
  };
  packMeta: {
    id: string;
    name: string;
    game: string;
    cardCount: number;
  };
}

/** Acknowledgement of received deck list with validation + missing card info. */
export interface DeckListAckMessage {
  type: 'deck-list-ack';
  valid: boolean;
  errors?: string[];
  missingCardIds?: string[];
  missingPackIds?: string[];
}

/** Request for asset pack data. */
export interface AssetPackRequestMessage {
  type: 'asset-pack-request';
  packId: string;
  mode: 'cards-only' | 'full-pack';
  /** Card IDs to include (for cards-only mode). */
  cardIds?: string[];
}

/** Offer to send asset pack data (sent after sender approves). */
export interface AssetPackOfferMessage {
  type: 'asset-pack-offer';
  packId: string;
  mode: 'cards-only' | 'full-pack';
  /** Total transfer size in bytes. */
  totalSize: number;
  /** Total number of chunks. */
  totalChunks: number;
  /** Number of cards included. */
  cardCount: number;
}

/** A chunk of asset pack data. */
export interface AssetPackChunkMessage {
  type: 'asset-pack-chunk';
  packId: string;
  chunkIndex: number;
  totalChunks: number;
  /** Base64-encoded data. */
  data: string;
}

/** Transfer complete signal. */
export interface AssetPackCompleteMessage {
  type: 'asset-pack-complete';
  packId: string;
  success: boolean;
}

/** Request denied or peer is blocked. */
export interface AssetPackDeniedMessage {
  type: 'asset-pack-denied';
  packId: string;
  reason: 'denied' | 'blocked';
}

/** Cancel an in-progress transfer. */
export interface AssetPackCancelMessage {
  type: 'asset-pack-cancel';
  packId: string;
}

export type AssetSharingMessage =
  | DeckListShareMessage
  | DeckListAckMessage
  | AssetPackRequestMessage
  | AssetPackOfferMessage
  | AssetPackChunkMessage
  | AssetPackCompleteMessage
  | AssetPackDeniedMessage
  | AssetPackCancelMessage;

// ---------------------------------------------------------------------------
// Block List (per-player, session-scoped)
// ---------------------------------------------------------------------------

export class PeerBlockList {
  private blocked = new Set<string>();
  private requestCounts = new Map<string, number>();
  private maxRequestsBeforeAutoBlock: number;

  constructor(maxRequestsBeforeAutoBlock = 3) {
    this.maxRequestsBeforeAutoBlock = maxRequestsBeforeAutoBlock;
  }

  /** Block a specific peer. */
  block(peerId: string): void {
    this.blocked.add(peerId);
  }

  /** Unblock a specific peer. */
  unblock(peerId: string): void {
    this.blocked.delete(peerId);
    this.requestCounts.delete(peerId);
  }

  /** Check if a peer is blocked. */
  isBlocked(peerId: string): boolean {
    return this.blocked.has(peerId);
  }

  /** Get list of all blocked peers. */
  getBlocked(): string[] {
    return [...this.blocked];
  }

  /**
   * Record a request from a peer. Returns true if the peer should be
   * auto-blocked (exceeded max requests).
   */
  recordRequest(peerId: string): boolean {
    const count = (this.requestCounts.get(peerId) ?? 0) + 1;
    this.requestCounts.set(peerId, count);

    if (count >= this.maxRequestsBeforeAutoBlock) {
      this.block(peerId);
      return true;
    }
    return false;
  }

  /** Reset request count for a peer (e.g., after successful transfer). */
  resetRequestCount(peerId: string): void {
    this.requestCounts.delete(peerId);
  }

  /** Clear all blocks and request counts. */
  clear(): void {
    this.blocked.clear();
    this.requestCounts.clear();
  }
}

// ---------------------------------------------------------------------------
// Transfer State Tracking
// ---------------------------------------------------------------------------

export type TransferDirection = 'sending' | 'receiving';

export type TransferStatus =
  | 'pending-consent'   // Waiting for local user to approve/accept
  | 'pending-remote'    // Waiting for remote peer to approve
  | 'transferring'      // Chunks being sent/received
  | 'complete'          // Transfer finished successfully
  | 'denied'            // Local user or remote peer denied
  | 'cancelled'         // Transfer was cancelled
  | 'error';            // Transfer failed

export interface TransferState {
  packId: string;
  peerId: string;
  direction: TransferDirection;
  mode: 'cards-only' | 'full-pack';
  status: TransferStatus;
  /** Card IDs involved (for cards-only mode). */
  cardIds?: string[];
  /** Total transfer size in bytes (known after offer). */
  totalSize?: number;
  /** Total chunks (known after offer). */
  totalChunks?: number;
  /** Chunks received/sent so far. */
  chunksCompleted: number;
  /** Timestamp when transfer started. */
  startedAt: number;
}

// ---------------------------------------------------------------------------
// Asset Sharing Session
// ---------------------------------------------------------------------------

/**
 * Manages the asset sharing state for a single P2P session.
 * Tracks active transfers, blocked peers, and provides methods
 * to create protocol messages.
 */
export class AssetSharingSession {
  readonly blockList: PeerBlockList;
  private transfers = new Map<string, TransferState>();

  constructor(maxRequestsBeforeAutoBlock = 3) {
    this.blockList = new PeerBlockList(maxRequestsBeforeAutoBlock);
  }

  // --- Transfer management ---

  /** Get all active transfers. */
  getTransfers(): TransferState[] {
    return [...this.transfers.values()];
  }

  /** Get a specific transfer by pack ID. */
  getTransfer(packId: string): TransferState | undefined {
    return this.transfers.get(packId);
  }

  /** Start tracking a new outgoing request (we are requesting from peer). */
  startRequest(
    packId: string,
    peerId: string,
    mode: 'cards-only' | 'full-pack',
    cardIds?: string[],
  ): TransferState {
    const state: TransferState = {
      packId,
      peerId,
      direction: 'receiving',
      mode,
      status: 'pending-remote',
      cardIds,
      chunksCompleted: 0,
      startedAt: Date.now(),
    };
    this.transfers.set(packId, state);
    return state;
  }

  /** Start tracking an incoming request (peer is requesting from us). */
  startIncomingRequest(
    packId: string,
    peerId: string,
    mode: 'cards-only' | 'full-pack',
    cardIds?: string[],
  ): TransferState {
    const state: TransferState = {
      packId,
      peerId,
      direction: 'sending',
      mode,
      status: 'pending-consent',
      cardIds,
      chunksCompleted: 0,
      startedAt: Date.now(),
    };
    this.transfers.set(packId, state);
    return state;
  }

  /** Update transfer status. */
  updateTransfer(
    packId: string,
    updates: Partial<Pick<TransferState, 'status' | 'totalSize' | 'totalChunks' | 'chunksCompleted'>>,
  ): TransferState | undefined {
    const transfer = this.transfers.get(packId);
    if (!transfer) return undefined;

    Object.assign(transfer, updates);
    return transfer;
  }

  /** Remove a completed/failed transfer. */
  removeTransfer(packId: string): void {
    this.transfers.delete(packId);
  }

  // --- Message factories ---

  /** Create a deck-list-share message. */
  static createDeckListShare(
    deckList: DeckListShareMessage['deckList'],
    packMeta: DeckListShareMessage['packMeta'],
  ): DeckListShareMessage {
    return { type: 'deck-list-share', deckList, packMeta };
  }

  /** Create a deck-list-ack message. */
  static createDeckListAck(
    valid: boolean,
    errors?: string[],
    missingCardIds?: string[],
    missingPackIds?: string[],
  ): DeckListAckMessage {
    return { type: 'deck-list-ack', valid, errors, missingCardIds, missingPackIds };
  }

  /** Create an asset-pack-request message. */
  static createRequest(
    packId: string,
    mode: 'cards-only' | 'full-pack',
    cardIds?: string[],
  ): AssetPackRequestMessage {
    return { type: 'asset-pack-request', packId, mode, cardIds };
  }

  /** Create an asset-pack-offer message. */
  static createOffer(
    packId: string,
    mode: 'cards-only' | 'full-pack',
    totalSize: number,
    totalChunks: number,
    cardCount: number,
  ): AssetPackOfferMessage {
    return { type: 'asset-pack-offer', packId, mode, totalSize, totalChunks, cardCount };
  }

  /** Create an asset-pack-chunk message from a Chunk. */
  static createChunkMessage(packId: string, chunk: Chunk): AssetPackChunkMessage {
    return {
      type: 'asset-pack-chunk',
      packId,
      chunkIndex: chunk.chunkIndex,
      totalChunks: chunk.totalChunks,
      data: chunk.data,
    };
  }

  /** Create an asset-pack-complete message. */
  static createComplete(packId: string, success: boolean): AssetPackCompleteMessage {
    return { type: 'asset-pack-complete', packId, success };
  }

  /** Create an asset-pack-denied message. */
  static createDenied(packId: string, reason: 'denied' | 'blocked'): AssetPackDeniedMessage {
    return { type: 'asset-pack-denied', packId, reason };
  }

  /** Create an asset-pack-cancel message. */
  static createCancel(packId: string): AssetPackCancelMessage {
    return { type: 'asset-pack-cancel', packId };
  }

  // --- Cleanup ---

  /** Reset all state (new session). */
  reset(): void {
    this.transfers.clear();
    this.blockList.clear();
  }
}

// ---------------------------------------------------------------------------
// Utility: Check for missing cards
// ---------------------------------------------------------------------------

/**
 * Given a deck list and a set of known card IDs, return the IDs that are missing.
 */
export function findMissingCards(
  deckCardIds: string[],
  knownCardIds: Set<string>,
): string[] {
  return deckCardIds.filter((id) => !knownCardIds.has(id));
}

/**
 * Check if an asset sharing message type is one we handle.
 */
export function isAssetSharingMessage(type: string): type is AssetSharingMessageType {
  return [
    'deck-list-share',
    'deck-list-ack',
    'asset-pack-request',
    'asset-pack-offer',
    'asset-pack-chunk',
    'asset-pack-complete',
    'asset-pack-denied',
    'asset-pack-cancel',
  ].includes(type);
}

import { describe, it, expect } from 'vitest';
import {
  PeerBlockList,
  AssetSharingSession,
  findMissingCards,
  isAssetSharingMessage,
} from './asset-sharing';

describe('PeerBlockList', () => {
  it('blocks and unblocks a peer', () => {
    const list = new PeerBlockList();
    expect(list.isBlocked('peer-1')).toBe(false);

    list.block('peer-1');
    expect(list.isBlocked('peer-1')).toBe(true);
    expect(list.getBlocked()).toEqual(['peer-1']);

    list.unblock('peer-1');
    expect(list.isBlocked('peer-1')).toBe(false);
    expect(list.getBlocked()).toEqual([]);
  });

  it('auto-blocks after max requests', () => {
    const list = new PeerBlockList(3);

    expect(list.recordRequest('peer-1')).toBe(false); // 1
    expect(list.recordRequest('peer-1')).toBe(false); // 2
    expect(list.recordRequest('peer-1')).toBe(true);  // 3 → auto-block
    expect(list.isBlocked('peer-1')).toBe(true);
  });

  it('does not auto-block different peers', () => {
    const list = new PeerBlockList(3);

    list.recordRequest('peer-1');
    list.recordRequest('peer-2');
    list.recordRequest('peer-1');

    expect(list.isBlocked('peer-1')).toBe(false);
    expect(list.isBlocked('peer-2')).toBe(false);
  });

  it('resets request count', () => {
    const list = new PeerBlockList(3);
    list.recordRequest('peer-1');
    list.recordRequest('peer-1');
    list.resetRequestCount('peer-1');
    list.recordRequest('peer-1'); // should be 1 again, not 3
    expect(list.isBlocked('peer-1')).toBe(false);
  });

  it('clears all state', () => {
    const list = new PeerBlockList();
    list.block('peer-1');
    list.block('peer-2');
    list.clear();
    expect(list.getBlocked()).toEqual([]);
  });
});

describe('AssetSharingSession', () => {
  it('tracks outgoing request transfer', () => {
    const session = new AssetSharingSession();
    const transfer = session.startRequest('pack-1', 'peer-1', 'cards-only', ['card-a']);

    expect(transfer.packId).toBe('pack-1');
    expect(transfer.direction).toBe('receiving');
    expect(transfer.status).toBe('pending-remote');
    expect(transfer.cardIds).toEqual(['card-a']);
  });

  it('tracks incoming request transfer', () => {
    const session = new AssetSharingSession();
    const transfer = session.startIncomingRequest('pack-1', 'peer-1', 'full-pack');

    expect(transfer.direction).toBe('sending');
    expect(transfer.status).toBe('pending-consent');
  });

  it('updates transfer state', () => {
    const session = new AssetSharingSession();
    session.startRequest('pack-1', 'peer-1', 'cards-only');

    const updated = session.updateTransfer('pack-1', {
      status: 'transferring',
      totalChunks: 10,
      chunksCompleted: 3,
    });

    expect(updated?.status).toBe('transferring');
    expect(updated?.totalChunks).toBe(10);
    expect(updated?.chunksCompleted).toBe(3);
  });

  it('returns undefined when updating non-existent transfer', () => {
    const session = new AssetSharingSession();
    expect(session.updateTransfer('nope', { status: 'complete' })).toBeUndefined();
  });

  it('removes transfer', () => {
    const session = new AssetSharingSession();
    session.startRequest('pack-1', 'peer-1', 'cards-only');
    session.removeTransfer('pack-1');
    expect(session.getTransfer('pack-1')).toBeUndefined();
  });

  it('lists all transfers', () => {
    const session = new AssetSharingSession();
    session.startRequest('pack-1', 'peer-1', 'cards-only');
    session.startIncomingRequest('pack-2', 'peer-2', 'full-pack');

    const transfers = session.getTransfers();
    expect(transfers).toHaveLength(2);
  });

  it('resets all state', () => {
    const session = new AssetSharingSession();
    session.startRequest('pack-1', 'peer-1', 'cards-only');
    session.blockList.block('peer-2');
    session.reset();

    expect(session.getTransfers()).toHaveLength(0);
    expect(session.blockList.getBlocked()).toEqual([]);
  });
});

describe('AssetSharingSession message factories', () => {
  it('creates deck-list-share message', () => {
    const msg = AssetSharingSession.createDeckListShare(
      { name: 'My Deck', game: 'onepiece', pack: 'OP01', leader: 'OP01-001', cards: { 'OP01-002': 4 } },
      { id: 'pack-1', name: 'OP01', game: 'onepiece', cardCount: 100 },
    );
    expect(msg.type).toBe('deck-list-share');
    expect(msg.deckList.name).toBe('My Deck');
    expect(msg.packMeta.cardCount).toBe(100);
  });

  it('creates deck-list-ack message', () => {
    const msg = AssetSharingSession.createDeckListAck(false, ['Too many cards'], ['OP01-099']);
    expect(msg.type).toBe('deck-list-ack');
    expect(msg.valid).toBe(false);
    expect(msg.errors).toEqual(['Too many cards']);
    expect(msg.missingCardIds).toEqual(['OP01-099']);
  });

  it('creates request message', () => {
    const msg = AssetSharingSession.createRequest('pack-1', 'cards-only', ['c1', 'c2']);
    expect(msg.type).toBe('asset-pack-request');
    expect(msg.mode).toBe('cards-only');
    expect(msg.cardIds).toEqual(['c1', 'c2']);
  });

  it('creates offer message', () => {
    const msg = AssetSharingSession.createOffer('pack-1', 'full-pack', 1024000, 22, 50);
    expect(msg.type).toBe('asset-pack-offer');
    expect(msg.totalSize).toBe(1024000);
  });

  it('creates chunk message', () => {
    const msg = AssetSharingSession.createChunkMessage('pack-1', {
      chunkIndex: 3,
      totalChunks: 10,
      data: 'base64data',
    });
    expect(msg.type).toBe('asset-pack-chunk');
    expect(msg.chunkIndex).toBe(3);
    expect(msg.packId).toBe('pack-1');
  });

  it('creates complete message', () => {
    const msg = AssetSharingSession.createComplete('pack-1', true);
    expect(msg.type).toBe('asset-pack-complete');
    expect(msg.success).toBe(true);
  });

  it('creates denied message', () => {
    const msg = AssetSharingSession.createDenied('pack-1', 'blocked');
    expect(msg.type).toBe('asset-pack-denied');
    expect(msg.reason).toBe('blocked');
  });

  it('creates cancel message', () => {
    const msg = AssetSharingSession.createCancel('pack-1');
    expect(msg.type).toBe('asset-pack-cancel');
  });
});

describe('findMissingCards', () => {
  it('returns missing card IDs', () => {
    const known = new Set(['c1', 'c2', 'c3']);
    const missing = findMissingCards(['c1', 'c4', 'c5'], known);
    expect(missing).toEqual(['c4', 'c5']);
  });

  it('returns empty when all present', () => {
    const known = new Set(['c1', 'c2']);
    expect(findMissingCards(['c1', 'c2'], known)).toEqual([]);
  });

  it('returns all when none known', () => {
    const known = new Set<string>();
    expect(findMissingCards(['c1', 'c2'], known)).toEqual(['c1', 'c2']);
  });
});

describe('isAssetSharingMessage', () => {
  it('recognizes valid message types', () => {
