/**
 * useGameCardImages Hook Tests
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, waitFor } from '@testing-library/react';
import { useGameCardImages } from './useGameCardImages';
import type { OnePieceCard } from '../game/modules/onepiece/types';

// Mock the asset loader
vi.mock('../assets/loader', () => ({
  getCardImageBlob: vi.fn(),
}));

let mockGetCardImageBlob: ReturnType<typeof vi.fn>;

function makeCard(id: string, name: string = 'Card'): OnePieceCard {
  return {
    id,
    name,
    cardType: 'character',
    cost: 1,
    power: 1000,
    color: ['red'],
    set: 'OP01',
    cardNumber: '001',
    rarity: 'C',
  };
}

// Mock URL.createObjectURL / revokeObjectURL
const createdUrls: string[] = [];
let urlCounter = 0;

beforeEach(async () => {
  vi.clearAllMocks();
  createdUrls.length = 0;
  urlCounter = 0;

  const loader = await import('../assets/loader');
  mockGetCardImageBlob = loader.getCardImageBlob as ReturnType<typeof vi.fn>;

  // Default: return a blob big enough to not be a placeholder
  mockGetCardImageBlob.mockResolvedValue({
    blob: new Blob(['x'.repeat(200)], { type: 'image/png' }),
    fromCache: true,
  });

  globalThis.URL.createObjectURL = vi.fn((blob: Blob) => {
    const url = `blob:mock-${urlCounter++}`;
    createdUrls.push(url);
    return url;
  });
  globalThis.URL.revokeObjectURL = vi.fn();
});

describe('useGameCardImages', () => {
  it('returns empty record when cards is null', () => {
    const { result } = renderHook(() =>
      useGameCardImages(null, new Map()),
    );
    expect(result.current).toEqual({});
  });

  it('returns empty record when cards is empty', () => {
    const { result } = renderHook(() =>
      useGameCardImages([], new Map()),
    );
    expect(result.current).toEqual({});
  });

  it('loads images for unique base card IDs', async () => {
    const cards = [makeCard('OP01-001', 'Luffy')];
    const packMap = new Map([['OP01-001', 'pack-1']]);

    const { result } = renderHook(() =>
      useGameCardImages(cards, packMap),
    );

    await waitFor(() => {
      expect(Object.keys(result.current).length).toBe(1);
    });

    expect(result.current['OP01-001']).toMatch(/^blob:/);
    expect(mockGetCardImageBlob).toHaveBeenCalledWith('pack-1', 'OP01-001', 'front');
  });

  it('maps multiple instance IDs to shared base card URL', async () => {
    const cards = [
      makeCard('OP01-010#0', 'Nami'),
      makeCard('OP01-010#1', 'Nami'),
      makeCard('OP01-010#2', 'Nami'),
      makeCard('OP01-010#3', 'Nami'),
    ];
    const packMap = new Map([['OP01-010', 'pack-1']]);

    const { result } = renderHook(() =>
      useGameCardImages(cards, packMap),
    );

    await waitFor(() => {
      expect(Object.keys(result.current).length).toBe(4);
    });

    // All 4 instances should share the same URL
    const urls = Object.values(result.current);
    expect(new Set(urls).size).toBe(1);

    // Only one blob should have been loaded (deduplicated)
    expect(mockGetCardImageBlob).toHaveBeenCalledTimes(1);
  });

  it('handles mixed base and instance IDs', async () => {
    const cards = [
      makeCard('OP01-001', 'Luffy'),     // leader, no suffix
      makeCard('OP01-010#0', 'Nami'),
      makeCard('OP01-010#1', 'Nami'),
      makeCard('OP01-020', 'Zoro'),       // single copy, no suffix
    ];
    const packMap = new Map([
      ['OP01-001', 'pack-1'],
      ['OP01-010', 'pack-1'],
      ['OP01-020', 'pack-1'],
    ]);

    const { result } = renderHook(() =>
      useGameCardImages(cards, packMap),
    );

    await waitFor(() => {
      expect(Object.keys(result.current).length).toBe(4);
    });

    // 3 unique base cards → 3 blob loads
    expect(mockGetCardImageBlob).toHaveBeenCalledTimes(3);
  });

  it('handles multi-pack cards with different packIds', async () => {
    const cards = [
      makeCard('OP01-001', 'Luffy'),
      makeCard('OP02-001', 'Ace'),
    ];
    const packMap = new Map([
      ['OP01-001', 'pack-1'],
      ['OP02-001', 'pack-2'],
    ]);

    const { result } = renderHook(() =>
      useGameCardImages(cards, packMap),
    );

    await waitFor(() => {
      expect(Object.keys(result.current).length).toBe(2);
    });

    expect(mockGetCardImageBlob).toHaveBeenCalledWith('pack-1', 'OP01-001', 'front');
    expect(mockGetCardImageBlob).toHaveBeenCalledWith('pack-2', 'OP02-001', 'front');
  });

  it('skips cards with no pack mapping', async () => {
    const cards = [
      makeCard('OP01-001', 'Luffy'),
      makeCard('UNKNOWN-001', 'Missing'),
    ];
    const packMap = new Map([['OP01-001', 'pack-1']]);

    const { result } = renderHook(() =>
      useGameCardImages(cards, packMap),
    );

    await waitFor(() => {
      expect(Object.keys(result.current).length).toBe(1);
    });

    expect(result.current['UNKNOWN-001']).toBeUndefined();
  });

  it('skips placeholder blobs (< 100 bytes)', async () => {
    mockGetCardImageBlob.mockResolvedValue({
      blob: new Blob(['tiny'], { type: 'image/png' }), // 4 bytes
      fromCache: true,
    });

    const cards = [makeCard('OP01-001', 'Luffy')];
    const packMap = new Map([['OP01-001', 'pack-1']]);

    const { result } = renderHook(() =>
      useGameCardImages(cards, packMap),
    );

    // Wait for the effect to settle — image should be skipped
    await waitFor(() => {
      expect(mockGetCardImageBlob).toHaveBeenCalled();
    });

    expect(result.current['OP01-001']).toBeUndefined();
  });

  it('handles getCardImageBlob errors gracefully', async () => {
    mockGetCardImageBlob.mockRejectedValue(new Error('IndexedDB error'));

    const cards = [makeCard('OP01-001', 'Luffy')];
    const packMap = new Map([['OP01-001', 'pack-1']]);

    const { result } = renderHook(() =>
      useGameCardImages(cards, packMap),
    );

    await waitFor(() => {
      expect(mockGetCardImageBlob).toHaveBeenCalled();
    });

    // Should return empty (error was swallowed)
    expect(result.current['OP01-001']).toBeUndefined();
  });

  it('revokes object URLs on unmount', async () => {
    const cards = [makeCard('OP01-001', 'Luffy')];
    const packMap = new Map([['OP01-001', 'pack-1']]);

    const { result, unmount } = renderHook(() =>
      useGameCardImages(cards, packMap),
    );

    await waitFor(() => {
      expect(Object.keys(result.current).length).toBe(1);
    });

    unmount();

    expect(URL.revokeObjectURL).toHaveBeenCalled();
  });
});

