  let cancelled = false;

  const loadImages = async () => {
    // Collect unique base card IDs and their instance IDs
    const baseToInstances = new Map<string, string[]>();
    for (const card of cards) {
      const base = baseCardId(card.id);
      const instances = baseToInstances.get(base) ?? [];
      instances.push(card.id);
      baseToInstances.set(base, instances);
    }

    const result: Record<string, string> = {};

    for (const [base, instanceIds] of baseToInstances) {
      if (cancelled) break;

      const packId = cardPackMap.get(base);
      if (!packId) continue;

      // Reuse existing URL if we already loaded this base card
      const existing = urlsRef.current.get(base);
      if (existing) {
        for (const id of instanceIds) {
          result[id] = existing;
        }
        continue;
      }

      try {
        const { blob } = await getCardImageBlob(packId, base, 'front');

        if (cancelled) break;

        // Skip placeholder blobs (1x1 transparent PNG is ~68 bytes)
        if (blob.size > 100) {
          const url = URL.createObjectURL(blob);
          urlsRef.current.set(base, url);
          for (const id of instanceIds) {
            result[id] = url;
          }
        }
      } catch {
        // Skip cards with missing images
      }
    }

    if (!cancelled) {
      setImageMap(result);
    }
  };

  loadImages();

  return () => {
    cancelled = true;
    for (const url of urlsRef.current.values()) {
      URL.revokeObjectURL(url);
    }
    urlsRef.current.clear();
  };
}, [cards, cardPackMap]);

