global.fetch = mockFetch;

// ---------------------------------------------------------------------------
// fetchFromHelia — timeout + path-splitting tests
// ---------------------------------------------------------------------------

describe('fetchFromHelia', () => {
  afterEach(() => {
    clearHeliaTestInstance();
    vi.restoreAllMocks();
  });

  it('returns null and clears timeout when Helia stalls past timeout', async () => {
    const clearSpy = vi.spyOn(globalThis, 'clearTimeout');

    const neverResolves = new Promise<Uint8Array>(() => {});
    const mockHelia = {
      blockstore: { get: () => neverResolves },
    } as unknown as Helia;
    setHeliaForTest(mockHelia);

    const result = await fetchFromHelia('QmFakeBareCID', 30);
    expect(result).toBeNull();
    expect(clearSpy).toHaveBeenCalled();
  });

  it('clears the timeout on a successful bare-CID fetch', async () => {
    const clearSpy = vi.spyOn(globalThis, 'clearTimeout');
    const fakeBlock = new Uint8Array([1, 2, 3]);
    const mockHelia = {
      blockstore: { get: async () => fakeBlock },
    } as unknown as Helia;
    setHeliaForTest(mockHelia);

    const result = await fetchFromHelia('QmFakeBareCID', 5000);
    expect(result).not.toBeNull();
    expect(result).toBeInstanceOf(Blob);
    expect(clearSpy).toHaveBeenCalled();
  });

  it('returns null when Helia is unavailable (heliaFailed)', async () => {
    // No test instance set — getHelia() will return null (no real init in test env)
    clearHeliaTestInstance();
    const result = await fetchFromHelia('QmFakeBareCID', 100);
    expect(result).toBeNull();
  });

  it('parses only the bare CID when cidString contains a path', async () => {
    const parsedCids: string[] = [];
    const fakeBlock = new Uint8Array([4, 5, 6]);

    // Mock unixfs so we can observe what CID was passed
    // The function itself calls CID.parse(bareCidString) — if path is present,
    // it should split on the first slash before parsing.
    // We verify indirectly: if the full string "QmFake/manifest.json" were passed
    // to CID.parse it would throw; the test should succeed instead.
    const asyncIterable = (async function* () {
      yield fakeBlock;
    })();

    const mockUnixfs = { cat: vi.fn(() => asyncIterable) };
    const mockHelia = {
      blockstore: { get: async () => { throw new Error('should not call blockstore for path CID'); } },
    } as unknown as Helia;
    setHeliaForTest(mockHelia);

    // We can't easily intercept the unixfs() call inside the module,
    // but we can verify that a CID string with a path does NOT throw.
    // If CID.parse received the full "QmFake/manifest.json" string it would throw
    // and the result would be null due to the catch block.
    // With the fix, it splits correctly, calls unixfs, and only fails because
    // QmFake is not a real CID (parse still throws on an invalid CID).
    const result = await fetchFromHelia('QmFakeBareCID/manifest.json', 100);
    // QmFakeBareCID is not a valid CID so parse throws → returns null (not a crash)
    expect(result).toBeNull();
  });
});

